import{z as l,x as i,o,c as d,q as B,j as A,D as t,d as e,s as n,S as s,b as a}from"./chunks/framework.C8m1ZpeB.js";const u=JSON.parse('{"title":"最后贷款人","description":"","frontmatter":{"title":"最后贷款人","date":"2026-09-18T00:00:00.000Z","section":"econ"},"headers":[],"relativePath":"econ/bm-lender-of-last-resort.md","filePath":"econ/bm-lender-of-last-resort.md","lastUpdated":1791063341000}'),C={name:"econ/bm-lender-of-last-resort.md"};function p(h,E,D,m,c,f){const r=i("Mermaid");return o(),d("div",null,[E[2]||(E[2]=B('<h1 id="最后贷款人" tabindex="-1">最后贷款人 <a class="header-anchor" href="#最后贷款人" aria-label="Permalink to &quot;最后贷款人&quot;">​</a></h1><div class="epigraph"><p>最后贷款人卖的不是钱，是协调：把「别人也会被接住」从谣言变成资产负债表上的事实。</p><footer>—— 据 Bagehot 1873、Rochet–Vives 2004 整理</footer></div><p><a href="/econ/bm-shadow-deep">上一课</a>把期限转换搬出表内，链条每一环都可在坏状态停滚。主干课的 <a href="/econ/lender-of-last-resort">最后贷款人</a>钉过 Bagehot 三原则与 inside/outside money 的兑换；本课补现代问题：当挤兑是协调博弈（第一课）、负债散布在影子链上（上一课），「区分流动性与清偿力」在事中还剩多少操作含义，弹性应当伸到哪里、以什么形状伸过去。后课默认已经读完本课。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>Bagehot 的处方有清晰对象：1873 年票据市场上可辨认的「好票据」。现代链上，挤兑是全市场的：抵押品被重估，而「好抵押」的认定标准本身基于市场价——市值下跌使好抵押变少，流动性不足与资不抵债在事中互相制造，处方的前提被它要治的病吃掉。缺口因此是双重的：理论上，最后贷款人什么时候能删掉坏均衡、什么时候只是在给损失融资；工程上，窗口该开给谁、押什么、按什么价押。</p><h3 id="写成协调装置" tabindex="-1">写成协调装置 <a class="header-anchor" href="#写成协调装置" aria-label="Permalink to &quot;写成协调装置&quot;">​</a></h3><p>把 LOLR 写进第一课的阈值结构（Rochet–Vives 2004）：央行的大额流动性承诺改变「跑」与「留」的收益比较，等价于把挤兑阈值 \\(\\theta^*\\) 向坏侧移出支撑——坏均衡不再有坐标。这解释了一个反复出现的经验：<strong>无限量承诺比实际借出多少重要</strong>。承诺是阈值移动，放款只是移动之后的结果；<a href="/econ/eurozone-crisis">欧元区危机</a>里「央行明确 LOLR 压坏均衡」的机制证据，在这里拿到博弈论地基。</p><p><span class="marginnote">美联储危机便利的存量在 2008 年末达到约 1.5 万亿美元量级（据美联储公开数据整理）：窗口的形状随可跑负债的分布变化，不是常数。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>形状的三步演化，每步对应负债形状的一次变化。①<strong>零售存款时代</strong>：贴现窗口对银行，Bagehot 处方原样适用——自由放款、惩罚利率、好抵押。②<strong>批发抵押品时代</strong>：可跑的债换成回购与商业票据，窗口跟着开到交易商与非银——2008 年的 PDCF、TSLF、CPFF 一族；抵押品资格与折扣成为主要杠杆。③<strong>市值断裂时代</strong>：市场价与清偿力脱钩，2023 年的 BTFP 以<strong>面值</strong>估值抵押品——把「好抵押」的口径从市场价切到面值，直接回应「事中分不清流动性与清偿力」的断裂。三条之外还有一对永恒取舍：建设性模糊保纪律、伤协调；清晰承诺强协调、把事前道德风险写进价格。第二课的激励与第一课的阈值在这对取舍里定价，没有免费档。</p><p><span class="marginnote">数字实例：设挤兑阈值为基本面低于 0.4 时人人开跑；央行「随时无限量」的确定性承诺把阈值推到 0.25，多数机构退出跑区——哪怕最终实际只放出 800 亿，起作用的也是那 1 万亿量级的承诺本身。</span></p>',11)),(o(),A(s,null,{default:t(()=>[n(r,{id:"mermaid-31",class:"mermaid",graph:"flowchart%20TD%0A%20%20PANIC%5B%22%E5%85%A8%E5%B8%82%E5%9C%BA%E6%8C%A4%E5%85%91%EF%BC%9A%E6%8A%B5%E6%8A%BC%E5%93%81%E8%A2%AB%E9%87%8D%E4%BC%B0%22%5D%20--%3E%20CB%5B%22%E5%A4%AE%E8%A1%8C%E6%89%BF%E8%AF%BA%EF%BC%9A%E9%87%8F%E3%80%81%E8%B5%84%E6%A0%BC%E3%80%81%E6%8A%B5%E6%8A%BC%E5%93%81%E5%8F%A3%E5%BE%84%22%5D%0A%20%20CB%20--%3E%20MOVE%5B%22%E9%98%88%E5%80%BC%20%CE%B8*%20%E7%A7%BB%E5%87%BA%E5%9D%8F%E5%8C%BA%22%5D%20--%3E%20DELETE%5B%22%E5%9D%8F%E5%9D%87%E8%A1%A1%E5%88%A0%E9%99%A4%22%5D%0A%20%20CB%20--%3E%7C%22%E6%B8%85%E5%81%BF%E5%8A%9B%E7%BC%BA%E5%8F%A3%22%7C%20DIV%5B%22%E5%88%86%E6%B5%81%EF%BC%9A%E5%A4%84%E7%BD%AE%E4%B8%8E%E6%B3%A8%E8%B5%84%22%5D%0A"})]),fallback:t(()=>[...E[0]||(E[0]=[e(" Loading... ",-1)])]),_:1})),E[3]||(E[3]=a("h2",{id:"机制",tabindex:"-1"},[e("机制 "),a("a",{class:"header-anchor",href:"#机制","aria-label":'Permalink to "机制"'},"​")],-1)),E[4]||(E[4]=a("p",null,[e("LOLR 是流动性不是资本——第二课的分工在救助场上兑现：它把 outside money 换进来、止住停滚，不改变损失的大小与归属。分流规则随之写定：能以惩罚性条款自偿的走窗口；洞在资产侧的走资产工具（收购承接、坏账剥离）；洞在资本侧的走处置与注资——保全股权的「流动性支持」不是 LOLR（"),a("a",{href:"/econ/too-big-to-fail"},"too-big-to-fail"),e(" 的口径）。弹性必须沿可跑负债的分布走：只在存款机构开窗，就是把协调问题留给影子链——2008 年的便利家族正是窗口沿链条上移的过程，2020 年 3 月的抢现与 2023 年的存款跑是同一原理在不同负债上重演。污名是工程约束：机构怕被看见进窗口，协调功能打折——这是窗口之外另造便利的直接理由。")],-1)),E[5]||(E[5]=a("p",null,[a("span",{class:"marginnote"},"术语翻译：「污名」指机构不敢进窗口，怕市场把进门读成「我有问题」的信号，股价与融资立刻遭殃；所以危机中常另设新便利、换名字换规则，让机构进门时不被直接对号入座。")],-1)),(o(),A(s,null,{default:t(()=>[n(r,{id:"mermaid-41",class:"mermaid",graph:"flowchart%20TD%0A%20%20INS%5B%22%E6%9C%BA%E6%9E%84%E6%9D%A5%E6%B1%82%E6%B5%81%E5%8A%A8%E6%80%A7%22%5D%20--%3E%20Q%7B%22%E6%B4%9E%E5%9C%A8%E5%93%AA%E4%B8%80%E4%BE%A7%EF%BC%9F%22%7D%0A%20%20Q%20--%3E%7C%22%E6%97%A0%E6%B4%9E%EF%BC%9A%E5%8F%AF%E8%87%AA%E5%81%BF%22%7C%20WIN%5B%22%E6%83%A9%E7%BD%9A%E6%80%A7%E6%9D%A1%E6%AC%BE%E8%B5%B0%E7%AA%97%E5%8F%A3%EF%BC%88LOLR%EF%BC%89%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B5%84%E4%BA%A7%E4%BE%A7%22%7C%20ASSET%5B%22%E8%B5%84%E4%BA%A7%E5%B7%A5%E5%85%B7%EF%BC%9A%E6%94%B6%E8%B4%AD%E6%89%BF%E6%8E%A5%E3%80%81%E5%9D%8F%E8%B4%A6%E5%89%A5%E7%A6%BB%22%5D%0A%20%20Q%20--%3E%7C%22%E8%B5%84%E6%9C%AC%E4%BE%A7%22%7C%20CAPD%5B%22%E5%A4%84%E7%BD%AE%E4%B8%8E%E6%B3%A8%E8%B5%84%22%5D%0A%20%20WIN%20--%3E%20KEEP%5B%22%E6%8D%9F%E5%A4%B1%E5%A4%A7%E5%B0%8F%E4%B8%8E%E5%BD%92%E5%B1%9E%E4%B8%8D%E5%8F%98%22%5D%0A%20%20CAPD%20--%3E%20EQU%5B%22%E4%BF%9D%E5%85%A8%E8%82%A1%E6%9D%83%E7%9A%84%E3%80%8C%E6%B5%81%E5%8A%A8%E6%80%A7%E6%94%AF%E6%8C%81%E3%80%8D%E4%B8%8D%E6%98%AF%20LOLR%22%5D%0A"})]),fallback:t(()=>[...E[1]||(E[1]=[e(" Loading... ",-1)])]),_:1})),E[6]||(E[6]=B('<h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>不重讲贴现窗口与地板系统（主干已钉，<a href="/econ/central-bank-balance-sheet">央行资产负债表</a>管负债侧工具）；国际维度——非美银行的美元缺口与互换线——留给下一课；道德风险只作参数，不做二元判断。阈值移动的幅度与成本也没有免费午餐：承诺越硬，事后被读成「救助」的概率越高；承诺越软，协调失败的代价越高。这条权衡在民主问责下怎么定价，是政治经济问题，本课只给结构。</p><p><span class="marginnote">直觉类比：建设性模糊像老师不宣布是否点名——学生（银行）不敢赌、自留更多缓冲，但真出事时协调也慢半拍；清晰承诺像宣布永远点名，协调变快、纪律没了，道德风险被写进事前价格。</span></p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>LOLR 的机制角色是协调装置：大额承诺移动阈值，坏均衡出支撑。</li><li>三步演化：贴现窗口、交易商与非银便利、面值口径的抵押品政策；窗口沿可跑负债的分布走。</li><li>流动性支持不改损失归属：清偿力缺口走处置与注资，混淆两者是 TBTF 的起点。</li><li>建设性模糊与清晰承诺在纪律与协调间定价，没有免费档。</li><li>污名使事中窗口打折，便利家族是它的工程补丁。</li><li>出处：Bagehot 1873；Rochet–Vives 2004；Diamond–Dybvig 1983 的政策含义；美联储便利文件。</li></ul>',5))])}const g=l(C,[["render",p]]);export{u as __pageData,g as default};
